## Baserom data-region extracts: claim understood ROM data spans without embedding
## copyrighted bytes in source. Offsets and lengths live here; content is read from
## the local gitignored gold ROM at build/check time only.
##
## Prefer residual unclaimed only. Inventory/build carve extract ranges out of
## GeneratedCodeSpans via carveSpanAroundHoles (adopted-style), so a mid-code
## data claim is technically supported — but verify_extract_overlap still gates
## residual-only waves that must not sit inside raw code_spans. New claims this
## wave stay residual free.
## Never commit the extracted bytes. See AGENTS.md copyright hygiene.

import
  std/[algorithm, os, strformat],
  ./common

const
  GoldBaseromPath* = "bin/Earthbound (U) [!].smc"
  GoldBaseromEnvVar* = "DECOMPBOUND_ROM"

type
  ExtractKind* = enum
    ekGfxLz
    ekApuPackage
    ekZeroPad
    ekScriptStream
    ekActionScript
    ekTable

  BaseromExtractSpan* = object
    name*: string
    offset*: int
    length*: int
    kind*: ExtractKind
    note*: string

